import net from 'node:net'
import fs from 'node:fs'
import yaml from 'js-yaml'

const cfg = yaml.load(fs.readFileSync(
  'C:/Users/skate_f/AppData/Roaming/io.github.clash-verge-rev.clash-verge-rev/clash-verge.yaml', 'utf8'))

const B = String.fromCharCode(92)
const pipe = B + B + '.' + B + 'pipe' + B + 'verge-mihomo-production-'
  + '7ee4e9f8c0289c964f2af77bb323ada481987cb3879963ebedf1c232e7285793'
const secret = cfg.secret || 'set-your-secret'

function api(method, path, body) {
  return new Promise((resolve) => {
    const req = `${method} ${path} HTTP/1.1\r\nHost: localhost\r\n`
      + `Authorization: Bearer ${secret}\r\nContent-Length: ${Buffer.byteLength(body || '')}\r\n`
      + `Connection: close\r\n\r\n${body || ''}`
    const s = net.connect(pipe)
    let buf = Buffer.alloc(0)
    s.on('connect', () => s.write(req))
    s.on('data', (d) => { buf = Buffer.concat([buf, d]) })
    s.on('error', (e) => resolve({ err: e.message }))
    s.on('close', () => {
      const text = buf.toString('utf8')
      const i = text.indexOf('\r\n\r\n')
      if (i < 0) return resolve({ raw: '' })
      const head = text.slice(0, i)
      const isChunked = /transfer-encoding:\s*chunked/i.test(head)
      const body = text.slice(i + 4)
      resolve({ raw: isChunked ? dechunk(body) : body, chunked: isChunked })
    })
    setTimeout(() => resolve({ err: 'timeout' }), 8000)
  })
}

function dechunk(s) {
  let out = ''
  let rest = s
  for (;;) {
    const nl = rest.indexOf('\r\n')
    if (nl < 0) break
    const size = parseInt(rest.slice(0, nl).trim(), 16)
    if (!Number.isFinite(size) || size === 0) break
    out += rest.slice(nl + 2, nl + 2 + size)
    rest = rest.slice(nl + 2 + size + 2)
  }
  return out
}

const r = await api('GET', '/rules')
if (r.err) { console.log('PIPE_ERROR:', r.err); process.exit(2) }

// The core may emit the payload twice on this pipe; take the largest JSON object.
