for (const line of r.raw.split('\n')) {
  const t = line.trim()
  if (!t.startsWith('{')) continue
  try {
    const j = JSON.parse(t)
    if (!best || (j.rules?.length || 0) > (best.rules?.length || 0)) best = j
  } catch { /* not this line */ }
}
if (!best) { console.log('未解析到规则 JSON，长度=', r.raw.length); process.exit(3) }

const rules = best.rules || []
console.log('=== 运行中 mihomo 核心的规则总数:', rules.length, '===')
rules.slice(0, 10).forEach((x) => {
  const hit = x.extra?.hitCount
  console.log(`  [${x.index}] ${x.type} ${x.payload} => ${x.proxy}`
    + (hit ? `   (hitCount=${hit})` : ''))
})

console.log('\n=== 新增的 Chat2API 直连规则命中情况 ===')
let total = 0
for (const x of rules.slice(0, 7)) {
  const h = x.extra?.hitCount || 0
  total += h
  console.log(`  ${x.payload.padEnd(24)} => ${x.proxy}   hitCount=${h}`)
}
console.log('  合计命中:', total)

const match = await api('GET', '/rules')
console.log('\n>>> 结论: 核心已加载并正在应用 qwen.ai DIRECT 规则 =',
  rules[0]?.payload === 'qwen.ai' && rules[0]?.proxy === 'DIRECT' ? 'YES' : 'NO')

