import net from 'node:net'
import fs from 'node:fs'
import yaml from 'js-yaml'

const cfg = yaml.load(fs.readFileSync(
  'C:/Users/skate_f/AppData/Roaming/io.github.clash-verge-rev.clash-verge-rev/clash-verge.yaml', 'utf8'))

const B = String.fromCharCode(92)
const pipe = B + B + '.' + B + 'pipe' + B + 'verge-mihomo-production-'
  + '7ee4e9f8c0289c964f2af77bb323ada481987cb3879963ebedf1c232e7285793'
const secret = cfg.secret || 'set-your-secret'

function api(method, path, body) {
  return new Promise((resolve) => {
    const req = `${method} ${path} HTTP/1.1\r\nHost: localhost\r\n`
      + `Authorization: Bearer ${secret}\r\nContent-Length: ${Buffer.byteLength(body || '')}\r\n`
      + `Connection: close\r\n\r\n${body || ''}`
    const s = net.connect(pipe)
    let buf = Buffer.alloc(0)
    s.on('connect', () => s.write(req))
    s.on('data', (d) => { buf = Buffer.concat([buf, d]) })
    s.on('error', (e) => resolve({ err: e.message }))
    s.on('close', () => {
      const text = buf.toString('utf8')
      const i = text.indexOf('\r\n\r\n')
      if (i < 0) return resolve({ raw: '' })
      const head = text.slice(0, i)
      const body2 = text.slice(i + 4)
      resolve({ raw: /transfer-encoding:\s*chunked/i.test(head) ? dechunk(body2) : body2 })
    })
    setTimeout(() => resolve({ err: 'timeout' }), 8000)
  })
}

function dechunk(s) {
  let out = ''
  let rest = s
  for (;;) {
    const nl = rest.indexOf('\r\n')
    if (nl < 0) break
    const size = parseInt(rest.slice(0, nl).trim(), 16)
    if (!Number.isFinite(size) || size === 0) break
    out += rest.slice(nl + 2, nl + 2 + size)
    rest = rest.slice(nl + 2 + size + 2)
  }
  return out
}

function hits() {
  return api('GET', '/rules').then((r) => {
    if (r.err) return {}
    let best = null
    for (const line of (r.raw || '').split('\n')) {
      const t = line.trim()
      if (!t.startsWith('{')) continue
      try {
        const j = JSON.parse(t)
        if (!best || (j.rules?.length || 0) > (best.rules?.length || 0)) best = j
      } catch { /* skip */ }
    }
    const out = {}
    for (const x of best?.rules || []) out[x.payload] = x.extra?.hitCount || 0
    return out
  })
}

const before = await hits()
console.log('BEFORE qwen.ai hitCount =', before['qwen.ai'] ?? '(absent)')

// Ask the container to hit chat.qwen.ai through the normal (Clash) path.
const { execSync } = await import('node:child_process')
try {
  execSync('docker exec chat2api node -e "fetch(\'https://chat.qwen.ai/api/v1/auths/signin\',{method:\'POST\',headers:{\'Content-Type\':\'application/json\'},body:\'{\}\'}).then(r=>console.log(\'status\',r.status)).catch(e=>console.log(\'err\',e.message))"',
    { stdio: 'inherit', timeout: 40000 })
} catch { /* reported above */ }

await new Promise((r) => setTimeout(r, 2500))
const after = await hits()
console.log('AFTER  qwen.ai hitCount =', after['qwen.ai'] ?? '(absent)')

const delta = (after['qwen.ai'] || 0) - (before['qwen.ai'] || 0)
console.log('')
console.log('>>> 容器流量是否经过 Clash:', delta > 0 ? 'YES (hitCount +' + delta + ')' : 'NO (hitCount 未变)')
if (delta > 0) {
  console.log('>>> 容器到 qwen.ai 的流量已被规则 [0] qwen.ai => DIRECT 接管')
}

