// Post-fix functional re-test for the local Chat2API container.
// Deliberately low volume: 6 upstream requests total, to stay well clear of
// the risk-control threshold that the 2026-09-25 incident tripped.
const BASE = 'http://127.0.0.1:8080'
const KEY = process.env.C2A_KEY
const results = []

function record(name, ok, detail) {
  results.push({ name, ok, detail })
  console.log(`${ok ? '  PASS' : '  FAIL'}  ${name}${detail ? '  ->  ' + detail : ''}`)
}

async function chat(body, { stream = false } = {}) {
  const res = await fetch(`${BASE}/v1/chat/completions`, {
    method: 'POST',
    headers: { Authorization: `Bearer ${KEY}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ stream, ...body }),
  })
  const text = await res.text()
  return { status: res.status, text, headers: res.headers }
}

function parseJson(t) { try { return JSON.parse(t) } catch { return null } }

// ---------------------------------------------------------------- 1. models
{
  const res = await fetch(`${BASE}/v1/models`, { headers: { Authorization: `Bearer ${KEY}` } })
  const j = await res.json().catch(() => null)
  const qwen = (j?.data || []).map((m) => m.id).filter((id) => /qwen/i.test(id))
  record('/v1/models lists Qwen models', res.status === 200 && qwen.length > 0,
    `${res.status}, ${qwen.length} qwen models`)
}

// ------------------------------------------------- 2. non-stream Qwen3.8-Max
let firstContent = ''
{
  const r = await chat({
    model: 'Qwen3.8-Max',
    messages: [{ role: 'user', content: 'Reply with exactly: PONG' }],
  })
  const j = parseJson(r.text)
  firstContent = j?.choices?.[0]?.message?.content ?? ''
  record('non-stream Qwen3.8-Max', r.status === 200 && firstContent.trim() === 'PONG',
    `http=${r.status} content=${JSON.stringify(firstContent.slice(0, 40))}`)
}

// ------------------------------------------------------- 3. second model
{
  const r = await chat({
    model: 'Qwen3.7-Plus',
    messages: [{ role: 'user', content: 'Reply with exactly: OK' }],
  })
  const j = parseJson(r.text)
  const c = j?.choices?.[0]?.message?.content ?? ''
  record('non-stream Qwen3.7-Plus', r.status === 200 && /OK/i.test(c),
    `http=${r.status} model=${j?.model} content=${JSON.stringify(c.slice(0, 30))}`)
