import net from 'node:net'
import { execSync } from 'node:child_process'

const B = String.fromCharCode(92)
const pipe = B + B + '.' + B + 'pipe' + B + 'verge-mihomo-production-'
  + '7ee4e9f8c0289c964f2af77bb323ada481987cb3879963ebedf1c232e7285793'
const secret = 'set-your-secret'

function api(path) {
  return new Promise((resolve) => {
    const req = `GET ${path} HTTP/1.1\r\nHost: localhost\r\n`
      + `Authorization: Bearer ${secret}\r\nContent-Length: 0\r\nConnection: close\r\n\r\n`
    const s = net.connect(pipe)
    let buf = Buffer.alloc(0)
    s.on('connect', () => s.write(req))
    s.on('data', (d) => { buf = Buffer.concat([buf, d]) })
    s.on('error', (e) => resolve({ err: e.message }))
    s.on('close', () => {
      const t = buf.toString('utf8')
      const i = t.indexOf('\r\n\r\n')
      if (i < 0) return resolve({ raw: '' })
      const head = t.slice(0, i)
      const body = t.slice(i + 4)
      resolve({ raw: /chunked/i.test(head) ? dechunk(body) : body })
    })
    setTimeout(() => resolve({ err: 'timeout' }), 8000)
  })
}

function dechunk(s) {
  let out = ''; let rest = s
  for (;;) {
    const nl = rest.indexOf('\r\n')
    if (nl < 0) break
    const size = parseInt(rest.slice(0, nl).trim(), 16)
    if (!Number.isFinite(size) || size === 0) break
    out += rest.slice(nl + 2, nl + 2 + size)
    rest = rest.slice(nl + 2 + size + 2)
  }
  return out
}

async function hits() {
  const r = await api('/rules')
  if (r.err) return {}
  let best = null
  for (const line of (r.raw || '').split('\n')) {
    const t = line.trim()
    if (!t.startsWith('{')) continue
    try {
      const j = JSON.parse(t)
      if (!best || (j.rules?.length || 0) > (best.rules?.length || 0)) best = j
    } catch { /* skip */ }
  }
  const out = {}
  for (const x of best?.rules || []) out[x.payload] = x.extra?.hitCount || 0
  return out
}

const before = await hits()
console.log('复测前 qwen.ai hitCount =', before['qwen.ai'] ?? '(absent)')

