// Decisive WAF experiment: same container, same egress, same instant.
// Question: is the Aliyun WAF challenge endpoint-sensitive (signin) or
// global (rate)? Fire both back to back, unauthenticated, and compare.
const endpoints = [
  ['signin  v2', 'https://chat.qwen.ai/api/v2/auths/signin', 'POST'],
  ['signin  v1', 'https://chat.qwen.ai/api/v1/auths/signin', 'POST'],
  ['chat    v2', 'https://chat.qwen.ai/api/v2/chat/completions', 'POST'],
  ['chats/new ', 'https://chat.qwen.ai/api/v2/chats/new', 'POST'],
  ['models  v1', 'https://chat.qwen.ai/api/v1/models', 'GET'],
]

const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/145.0.0.0 Safari/537.36'

for (const [name, url, method] of endpoints) {
  const t0 = Date.now()
  try {
    const res = await fetch(url, {
      method,
      headers: {
        'Content-Type': 'application/json',
        Accept: 'application/json',
        'Accept-Language': 'zh-CN,zh;q=0.9,en;q=0.8',
        Origin: 'https://chat.qwen.ai',
        Referer: 'https://chat.qwen.ai/',
        source: 'web',
        Version: '0.2.67',
        'User-Agent': UA,
      },
      ...(method === 'POST' ? { body: '{}' } : {}),
    })
    const text = await res.text()
    const waf = /aliyun_waf_aa/.test(text)
    const ct = res.headers.get('content-type') || ''
    const acw = /acw_tc=/.test(res.headers.get('set-cookie') || '') ? 'yes' : 'no'
    console.log(
      `  ${name}  http=${res.status}  waf=${waf ? 'YES <<<' : 'no '}  ` +
      `set-cookie acw_tc=${acw}  ${ct.split(';')[0]}  ${Date.now() - t0}ms`,
    )
    if (waf) {
      const m = text.match(/aliyun_waf_aa" content="([a-f0-9]+)"/)
      console.log(`      fingerprint: ${m ? m[1] : 'n/a'}`)
    }
  } catch (e) {
    console.log(`  ${name}  ERROR ${e.message}`)
  }
}

