// Decrypt one Qwen account's cookie jar locally and show which cookie names
// it actually contains. Read-only: prints cookie NAMES, never values.
import crypto from 'node:crypto'
import fs from 'node:fs'

const KEY = process.env.C2A_KEY_ENC
const FILE = process.env.C2A_DATA

function decrypt(blob) {
  const raw = String(blob || '')
  if (!raw.startsWith('c2a:v1:')) return { ok: false, reason: 'not c2a:v1' }
  const b64 = raw.slice('c2a:v1:'.length)
  // layout: salt(16) | iv(12) | tag(16) | ciphertext
  const buf = Buffer.from(b64, 'base64')
  const salt = buf.subarray(0, 16)
  const iv = buf.subarray(16, 28)
  const tag = buf.subarray(28, 44)
  const ct = buf.subarray(44)
  const key = crypto.scryptSync(KEY, salt, 32)
  const d = crypto.createDecipheriv('aes-256-gcm', key, iv)
  d.setAuthTag(tag)
  return { ok: true, text: Buffer.concat([d.update(ct), d.final()]).toString('utf8') }
}

const d = JSON.parse(fs.readFileSync(FILE, 'utf8'))
const q = (d.accounts || []).filter((a) => /qwen/i.test(a.providerId || ''))
console.log(`  qwen 账号数: ${q.length}`)

let withTokenCookie = 0
let acwTc = 0
const names = new Set()
let sample = null

for (const a of q) {
  const r = decrypt(a.credentials?.cookies)
  if (!r.ok) { console.log(`  ${a.id} 解密失败: ${r.reason}`); continue }
  const ck = r.text
  if (/(?:^|;\s*)token=/.test(ck)) withTokenCookie++
  if (/acw_tc=/.test(ck)) acwTc++
  for (const m of ck.matchAll(/([A-Za-z0-9_.-]+)=/g)) names.add(m[1])
  if (!sample) sample = { id: a.id, len: ck.length }
}

console.log(`  含 token= 会话 cookie 的账号: ${withTokenCookie}/${q.length}`)
console.log(`  含 acw_tc 的账号:            ${acwTc}/${q.length}`)
console.log(`  cookie 明文长度(样本):        ${sample?.len}`)
console.log(`  出现过的 cookie 名:           ${[...names].sort().join(', ')}`)
console.log('')
console.log(`  >>> isQwenAiWebSessionReady() 会判定: ${withTokenCookie > 0 ? 'READY' : 'NOT READY (触发 339 次 signin)'}`)

