import net from 'node:net'
import fs from 'node:fs'
import yaml from 'js-yaml'

const cfg = yaml.load(fs.readFileSync(
  'C:/Users/skate_f/AppData/Roaming/io.github.clash-verge-rev.clash-verge-rev/clash-verge.yaml', 'utf8'))
const B = String.fromCharCode(92)
const pipe = B + B + '.' + B + 'pipe' + B + 'verge-mihomo-production-'
  + '7ee4e9f8c0289c964f2af77bb323ada481987cb3879963ebedf1c232e7285793'

function api(path) {
  return new Promise((resolve) => {
    const req = `GET ${path} HTTP/1.1\r\nHost: localhost\r\n`
      + `Authorization: Bearer ${cfg.secret}\r\nContent-Length: 0\r\nConnection: close\r\n\r\n`
    const s = net.connect(pipe)
    let buf = Buffer.alloc(0)
    s.on('connect', () => s.write(req))
    s.on('data', (d) => { buf = Buffer.concat([buf, d]) })
    s.on('error', (e) => resolve({ err: e.message }))
    s.on('close', () => {
      const t = buf.toString('utf8'); const i = t.indexOf('\r\n\r\n')
      if (i < 0) return resolve({ raw: '' })
      const head = t.slice(0, i); const body = t.slice(i + 4)
      resolve({ raw: /chunked/i.test(head) ? dechunk(body) : body })
    })
    setTimeout(() => resolve({ err: 'timeout' }), 8000)
  })
}
function dechunk(s) {
  let out = ''; let rest = s
  for (;;) {
    const nl = rest.indexOf('\r\n')
    if (nl < 0) break
    const size = parseInt(rest.slice(0, nl).trim(), 16)
    if (!Number.isFinite(size) || size === 0) break
    out += rest.slice(nl + 2, nl + 2 + size)
    rest = rest.slice(nl + 2 + size + 2)
  }
  return out
}

const r = await api('/rules')
if (r.err) { console.log('PIPE_ERROR:', r.err); process.exit(2) }
let best = null
for (const line of (r.raw || '').split('\n')) {
  const t = line.trim(); if (!t.startsWith('{')) continue
  try { const j = JSON.parse(t); if (!best || (j.rules?.length || 0) > (best.rules?.length || 0)) best = j } catch { /* */ }
}
if (!best) { console.log('未取到规则'); process.exit(3) }
console.log(`运行中 mihomo 核心规则数: ${best.rules.length}`)
best.rules.slice(0, 7).forEach((x) => {
  console.log(`  [${x.index}] ${x.type} ${x.payload} => ${x.proxy}  (hitCount=${x.extra?.hitCount ?? 0})`)
})
const qwen = best.rules.find((x) => x.payload === 'qwen.ai')
console.log('')
console.log('>>> qwen.ai 直连规则是否仍在运行中的核心里:',
  qwen && qwen.proxy === 'DIRECT' ? 'YES ✅（代理开着也能直连）' : 'NO ❌')

